application/json.schema:
{
  "title": "Audio to Text Transcriber input",
  "type": "object",
  "schemaVersion": 1,
  "properties": {
    "audioUrls": {
      "title": "Audio or video file URLs",
      "type": "array",
      "editor": "stringList",
      "description": "Direct links to audio or video files (mp3, wav, m4a, ogg, flac, webm, mp4 and other formats ffmpeg reads). Up to 300 MB per file. Not for Instagram, TikTok or YouTube page links.",
      "prefill": [
        "https://raw.githubusercontent.com/ggerganov/whisper.cpp/master/samples/jfk.wav"
      ],
      "default": [
        "https://raw.githubusercontent.com/ggerganov/whisper.cpp/master/samples/jfk.wav"
      ]
    },
    "model": {
      "title": "Whisper model",
      "type": "string",
      "editor": "select",
      "enum": [
        "tiny",
        "base",
        "small"
      ],
      "enumTitles": [
        "Tiny (fastest)",
        "Base (balanced)",
        "Small (most accurate, slowest)"
      ],
      "default": "base",
      "description": "Bigger models are more accurate and slower. The price per minute is the same for every model."
    },
    "language": {
      "title": "Language",
      "type": "string",
      "editor": "textfield",
      "description": "Spoken language as a two-letter code (en, fr, es, de ...). Leave empty to detect it automatically."
    },
    "translateToEnglish": {
      "title": "Translate to English",
      "type": "boolean",
      "default": false,
      "description": "Output an English translation instead of the original-language transcript."
    },
    "wordTimestamps": {
      "title": "Word timestamps",
      "type": "boolean",
      "default": false,
      "description": "Add start and end times for each word inside each segment."
    },
    "skipSilence": {
      "title": "Skip silence",
      "type": "boolean",
      "default": true,
      "description": "Skip long silent stretches before transcribing (voice activity detection). Faster and fewer made-up lines on music or silence."
    },
    "maxMinutesPerFile": {
      "title": "Max minutes per file",
      "type": "integer",
      "minimum": 1,
      "maximum": 180,
      "default": 60,
      "description": "Files longer than this are skipped with a reason and not charged."
    }
  },
  "required": [
    "audioUrls"
  ]
}

